const raw = String($json.body || $json.data || $json || '');
const lines = raw.split(/\r?\n/).filter(Boolean);
if (!lines.length) return [];
const headers = lines.shift().split(',').map((h) => h.trim());
function parseLine(line) {
  const values = line.split(',');
  const obj = {};
  headers.forEach((header, index) => { obj[header] = (values[index] || '').trim(); });
  return obj;
}
return lines.map((line, index) => {
  const row = parseLine(line);
  return { json: {
    prospect_id: row.prospect_id || `gsheet-${index + 1}`,
    organization_name: row.organization_name || row.company_name || row.name || '',
    website: row.website || row.domain || '',
    country: row.country || "Côte d'Ivoire",
    organization_type: row.organization_type || 'organisation à qualifier',
    sector_guess: row.sector_guess || row.industry || 'secteur à confirmer',
    decision_maker_name: row.decision_maker_name || row.contact_name || 'Décideur à confirmer',
    target_email: row.target_email || row.email || '',
    custom_page_paths_csv: row.custom_page_paths_csv || '',
    booking_link_45min: row.booking_link_45min || 'https://calendly.com/contact-transferai/30min',
    commercial_priority_default: row.commercial_priority_default || 'tier1',
    research_scope: row.research_scope || 'public_web_only',
    source_backend: 'google_sheets',
    raw_source_id: row.prospect_id || `gsheet-${index + 1}`,
    outreach_attempt_count: Number(row.outreach_attempt_count || 0),
    last_response_status: row.last_response_status || '',
    last_sequence_result: row.last_sequence_result || '',
    stop_reason: row.stop_reason || '',
    paused: ['true','1','yes'].includes(String(row.paused || '').toLowerCase()),
    do_not_contact: ['true','1','yes'].includes(String(row.do_not_contact || '').toLowerCase()),
    niche_status: row.niche_status || '',
    next_action_at: row.next_action_at || null
  } };
});

const items = $input.all().map((item) => item.json);
const config = $('Set Batch Config').first().json;
const sentToday = Array.isArray($('Fetch Today Outreach Count').first().json) ? $('Fetch Today Outreach Count').first().json.length : 0;
const batchRunResponse = $('Create Batch Run').first().json;
const batchRunRow = Array.isArray(batchRunResponse) ? batchRunResponse[0] : batchRunResponse;
const batchRunId = batchRunRow?.id || null;
const dailyLimit = Number(config.daily_send_limit || 5);
const maxAttempts = Number(config.max_attempts_per_prospect || 3);
const remainingCapacity = Math.max(dailyLimit - sentToday, 0);
const activeNiches = String(config.active_niche_list_csv || '').split(',').map((n) => n.trim()).filter(Boolean);
let scheduled = 0;
const outputs = [];
for (const prospect of items) {
  let processDecision = 'skip';
  let stopReason = '';
  const prospectNiche = String(prospect.niche_status || '').trim();
  const nicheMatch = activeNiches.length === 0 || activeNiches.includes(prospectNiche);
  if (!nicheMatch) {
    stopReason = 'inactive_niche';
  } else if (!prospect.organization_name || !prospect.website) {
    stopReason = 'missing_minimum_profile';
  } else if (prospect.do_not_contact) {
    stopReason = 'do_not_contact';
  } else if (prospect.paused) {
    stopReason = 'prospect_paused';
  } else if (prospect.stop_reason) {
    stopReason = prospect.stop_reason;
  } else if (Number(prospect.outreach_attempt_count || 0) >= maxAttempts) {
    stopReason = 'max_attempts_reached';
  } else if (['interested','meeting_booked','not_interested','unsubscribed'].includes(String(prospect.last_response_status || '').toLowerCase())) {
    stopReason = 'sequence_already_closed';
  } else if (String(prospect.last_sequence_result || '').toLowerCase() === 'no_niche') {
    stopReason = 'niche_not_relevant';
  } else if (scheduled >= remainingCapacity) {
    stopReason = 'daily_quota_reached';
  } else {
    processDecision = 'process_now';
    scheduled += 1;
  }
  outputs.push({
    json: {
      ...prospect,
      batch_run_id: batchRunId,
      batch_run_label: config.batch_run_label,
      active_campaign_label: config.active_campaign_label || null,
      active_niche_list_csv: config.active_niche_list_csv || '',
      daily_send_limit: dailyLimit,
      sent_today: sentToday,
      remaining_capacity: remainingCapacity,
      process_decision: processDecision,
      batch_stop_reason: stopReason || null
    }
  });
}
return outputs;

const items = $input.all().map((item) => item.json);
const config = $('Set Batch Config').first().json;
const processed = items.filter((item) => item.batch_status === 'dispatched_to_v3').length;
const skipped = items.filter((item) => item.batch_status === 'skipped_in_batch').length;
const skipReasons = {};
for (const item of items.filter((entry) => entry.batch_stop_reason)) {
  skipReasons[item.batch_stop_reason] = (skipReasons[item.batch_stop_reason] || 0) + 1;
}
const renderedCataloguesCount = items.filter((item) => item.catalogue_artifact).length;
const renderedDecksCount = items.filter((item) => item.deck_artifact).length;
const renderErrorCount = items.filter((item) => item.render_errors && Object.keys(item.render_errors).length > 0).length;
const attachmentsTotalCount = items.reduce((sum, item) => sum + Number(item.attachments_count || 0), 0);
const batchRunResponse = $('Create Batch Run').first().json;
const batchRunRow = Array.isArray(batchRunResponse) ? batchRunResponse[0] : batchRunResponse;
return [{ json: {
  batch_run_id: batchRunRow?.id || null,
  batch_run_label: items[0]?.batch_run_label || batchRunRow?.run_label || 'batch-run',
  active_campaign_label: items[0]?.active_campaign_label || config.active_campaign_label || null,
  active_niche_list_csv: items[0]?.active_niche_list_csv || config.active_niche_list_csv || '',
  child_workflow_id_v3: 'PvralFMyr6MdWe8I',
  child_workflow_label_v3: 'TransferAI Prospecting V3 CRM Enhanced [FINAL]',
  processed_count: processed,
  skipped_count: skipped,
  rendered_catalogues_count: renderedCataloguesCount,
  rendered_decks_count: renderedDecksCount,
  rendered_attachments_total: attachmentsTotalCount,
  render_error_count: renderErrorCount,
  skip_reasons: skipReasons,
  generated_at: new Date().toISOString()
} }];
